CREATE POLICY fin1_receipts_boundary ON storage.objects AS RESTRICTIVE FOR ALL TO public USING (bucket_id <> 'financeiro-comprovantes' OR (SELECT public.has_any_role(auth.uid(), ARRAY['admin','administrativo','gestor','diretor']::public.user_role[]))) WITH CHECK (bucket_id <> 'financeiro-comprovantes' OR (SELECT public.has_any_role(auth.uid(), ARRAY['admin','administrativo','gestor','diretor']::public.user_role[])));
CREATE POLICY fin1_receipts_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='financeiro-comprovantes' AND (SELECT public.has_any_role(auth.uid(), ARRAY['admin','administrativo','gestor','diretor']::public.user_role[])));
CREATE POLICY fin1_receipts_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='financeiro-comprovantes' AND (SELECT public.has_any_role(auth.uid(), ARRAY['admin','administrativo','gestor','diretor']::public.user_role[])));
CREATE POLICY fin1_receipts_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id='financeiro-comprovantes' AND (SELECT public.has_any_role(auth.uid(), ARRAY['admin','administrativo','gestor','diretor']::public.user_role[]))) WITH CHECK (bucket_id='financeiro-comprovantes' AND (SELECT public.has_any_role(auth.uid(), ARRAY['admin','administrativo','gestor','diretor']::public.user_role[])));
CREATE POLICY fin1_receipts_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id='financeiro-comprovantes' AND (SELECT public.has_role(auth.uid(),'admin'::public.user_role)));